(function(root){
  'use strict';
  const C=AuthCore,N=(tag,text,cls)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e;};
  let initial={};try{initial=JSON.parse(document.getElementById('auth-context')?.dataset.app||'{}');}catch{}
  function state(){return {...initial,supported:document.getElementById('auth-context')?.dataset.supported==='true',authenticated:!!initial.user,displayName:initial.user?.name||'',returnTo:C.returnPath((document.getElementById('auth-context')?.dataset.returnTo||location.pathname+location.search)+(location.hash.startsWith('#menu=')&&!document.getElementById('auth-context')?.dataset.returnTo?.includes('#')?location.hash:''))};}
  const can=permission=>!!initial.user&&(initial.user.permissions.includes('*')||initial.user.permissions.includes(permission));
  async function request(path,data){const r=await fetch(path,{method:data===undefined?'GET':'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-CSRF-Token':initial.user?.csrfToken||''},...(data===undefined?{}:{body:JSON.stringify(data)})});const j=await r.json();if(!r.ok)throw Object.assign(Error(j.error?.message||'요청을 처리하지 못했습니다.'),{status:r.status});return j;}
  function go(path){location.assign(C.returnPath(path));}
  const button=(text,fn,cls='auth-secondary')=>{const b=N('button',text,cls);b.type='button';b.addEventListener('click',fn);return b;};
  function field(form,label,name,type='text',value='',required=true){const wrap=N('label',undefined,'auth-field'),input=N('input');input.name=name;input.type=type;input.value=value;input.required=required;input.autocomplete=type==='password'?'current-password':name==='loginId'?'username':'off';input.maxLength=type==='password'?64:100;wrap.append(N('span',label),input);form.append(wrap);return input;}
  async function logout(){try{await request('/api/auth/logout',{});location.assign(C.signInPath(location.pathname+location.search+location.hash));}catch(e){alert(e.message);}}
  function passwordForm(){const form=N('form',undefined,'auth-form'),a=field(form,'현재 비밀번호','currentPassword','password'),b=field(form,'새 비밀번호','password','password'),c=field(form,'새 비밀번호 확인','confirm','password'),message=N('p',undefined,'auth-message'),submit=N('button','비밀번호 변경 후 다시 로그인','auth-primary');b.autocomplete=c.autocomplete='new-password';submit.type='submit';form.append(submit,message);form.addEventListener('submit',async e=>{e.preventDefault();if(b.value!==c.value){message.textContent='새 비밀번호가 일치하지 않습니다.';return;}submit.disabled=true;try{await request('/api/auth/password',{currentPassword:a.value,password:b.value});go('/login');}catch(x){message.textContent=x.message;}finally{a.value=b.value=c.value='';submit.disabled=false;}});return form;}
  function accountContent(){const s=state(),box=N('section',undefined,'auth-account');box.append(N('p',s.authenticated?s.displayName+' · '+s.user.loginId+' · '+s.user.company.code:'앱 ID로 로그인하세요.'));if(s.authenticated)box.append(passwordForm(),button('로그아웃',logout));return box;}
  function drawLogin(){const s=state(),panel=document.getElementById('login-panel');if(!panel)return;const status=document.getElementById('login-status'),info=document.getElementById('login-account'),actions=document.getElementById('login-actions');actions.replaceChildren();status.textContent=!s.initialized?'최초 관리자 등록':'앱 ID로 로그인';info.textContent=s.authenticated?s.displayName+'님으로 로그인되어 있습니다.':!s.initialized?'회사와 첫 관리자 계정을 등록하세요.':'이 ERP에 등록한 회사코드·ID·비밀번호를 입력하세요.';
    if(!s.supported){info.textContent='서버 미리보기에서 계정 기능을 사용할 수 있습니다.';return;}
    if(s.authenticated){actions.append(button('ERP 열기',()=>go(s.user.kind==='customer'?'/portal':s.returnTo),'auth-primary'),button('로그아웃',logout));return;}
    if(!s.initialized&&!s.bootstrapAllowed){info.textContent='사이트 소유자가 먼저 관리자 계정을 등록해야 합니다.';return;}
    const setup=!s.initialized,form=N('form',undefined,'auth-form');form.autocomplete='on';const company=field(form,'회사코드','companyCode','text',s.company?.code||''),login=field(form,'사용자 ID','loginId'),password=field(form,'비밀번호','password','password');company.maxLength=20;login.maxLength=40;let companyName,name,confirm;if(setup){password.autocomplete='new-password';companyName=field(form,'회사명','companyName');name=field(form,'관리자 이름','name');confirm=field(form,'비밀번호 확인','confirm','password');confirm.autocomplete='new-password';form.append(N('p','비밀번호는 12자 이상이며, 영문·숫자 ID는 3자 이상입니다.','auth-help'));}const submit=N('button',setup?'관리자 등록 후 로그인':'로그인','auth-primary');submit.type='submit';const message=N('p',undefined,'auth-message');message.setAttribute('role','alert');form.append(submit,message);actions.append(form);
    form.addEventListener('submit',async e=>{e.preventDefault();if(confirm&&password.value!==confirm.value){message.textContent='비밀번호가 일치하지 않습니다.';return;}submit.disabled=true;message.textContent='확인 중입니다…';try{const data={companyCode:company.value,loginId:login.value,password:password.value};if(setup)await request('/api/auth/setup',{...data,companyName:companyName.value,name:name.value});const r=await request('/api/auth/login',data);password.value='';if(confirm)confirm.value='';go(r.returnTo||s.returnTo);}catch(x){message.textContent=x.message;password.value='';if(confirm)confirm.value='';if(setup){const latest=await request('/api/auth/status').catch(()=>null);if(latest?.initialized){initial={...initial,...latest};drawLogin();}}}finally{submit.disabled=false;}});
  }
  function refresh(user){if(user)initial.user=user;const brand=document.getElementById('home-logo');if(brand&&initial.user?.company){brand.replaceChildren();if(initial.user.company.logo){const img=N('img');img.src=initial.user.company.logo;img.alt=initial.user.company.name;img.style.maxHeight='32px';img.style.maxWidth='150px';brand.append(img);}else brand.textContent=initial.user.company.name||'자동화 ERP';}const company=document.getElementById('footer-company');if(company)company.textContent=initial.user?.company?.name||'개발 검증용';}
  function init(){const s=state(),host=document.getElementById('account-actions');if(host){host.replaceChildren(N('span',s.authenticated?s.displayName+' · '+s.user.loginId:'앱 로그인 필요','auth-status'),button(s.authenticated?'로그아웃':'로그인',s.authenticated?logout:()=>go(C.signInPath(location.pathname+location.search+location.hash)),'auth-header-link'));}refresh();drawLogin();}
  root.AuthUI={init,accountContent,state,request,can,refresh,logout,settings:()=>initial.user?.settings||{}};init();window.addEventListener('pageshow',event=>{if(event.persisted&&state().supported)location.reload();});
})(typeof globalThis==='object'?globalThis:this);
